    @font-face {
    font-family: 'vazirmatn';
    src: url("/design/site/assets/fonts/Vazirmatn-VariableFont_wght.ttf") format('woff2');
}

* {
    box-sizing: border-box;
    font-family: 'vazirmatn';
}

body {
    background: #E4E6ED !important;
    margin: 0;
    padding: 0;
    direction: rtl;
}

    /* ============================= TOKENS ============================= */
    :root {
      --navy-950: #0A2340;
      --navy-900: #0D2B4E;
      --navy-800: #123C6D;
      --navy-700: #164A85;
      --navy-600: #1F5C9E;
      --navy-500: #3572B0;
      --navy-100: #E8EEF6;
      --navy-050: #F3F6FA;
      --gold-500: #C9A227;
      --gold-100: #FBF3DA;
      --white: #FFFFFF;
      --ink-900: #17222E;
      --ink-700: #374357;
      --ink-500: #5B6B7C;
      --ink-300: #93A2B3;
      --border: #E1E7EE;
      --border-soft: #EEF2F7;
      --red-600: #C6423F;
      --red-100: #FBEAE9;
      --green-600: #2E8F63;
      --green-100: #E7F5EE;
      --amber-600: #B4791A;
      --amber-100: #FBF0DE;
      --shadow-sm: 0 1px 2px rgba(13, 43, 78, .06);
      --shadow-md: 0 6px 20px -4px rgba(13, 43, 78, .14);
      --shadow-lg: 0 20px 45px -12px rgba(13, 43, 78, .28);
      --radius-sm: 10px;
      --radius-md: 16px;
      --radius-lg: 22px;
      --font-body: 'Vazirmatn', sans-serif;
      --font-mono: 'JetBrains Mono', monospace;
    }

