    button {
      font-family: inherit;
    }

    input,
    textarea,
    select {
      font-family: inherit;
    }

    .num {
      font-family: var(--font-mono);
      direction: ltr;
      unicode-bidi: isolate;
    }

    a {
      color: inherit;
    }

    ::selection {
      background: var(--navy-600);
      color: #fff;
    }

    :focus-visible {
      outline: 2.5px solid var(--navy-600);
      outline-offset: 2px;
      border-radius: 6px;
    }

    /* respect reduced motion */
    @media (prefers-reduced-motion: reduce) {
      * {
        animation-duration: .001ms !important;
        transition-duration: .001ms !important;
      }
    }

    .screen {
      display: none;
    }

    .screen.active {
      display: block;
    }

    /* ============================= HORIZON MOTIF (signature element) ============================= */
    /* Alborz ridge + Caspian shoreline — used as a quiet identity mark, not decoration for its own sake */
    .horizon {
      position: absolute;
      inset-inline: 0;
      bottom: 0;
      height: 190px;
      overflow: hidden;
      pointer-events: none;
    }

    .horizon svg {
      position: absolute;
      bottom: 0;
      width: 100%;
      height: 100%;
    }

    .horizon .waveA {
      animation: driftA 22s linear infinite;
    }

    .horizon .waveB {
      animation: driftB 30s linear infinite;
    }

    @keyframes driftA {
      from {
        transform: translateX(0)
      }

      to {
        transform: translateX(-320px)
      }
    }

    @keyframes driftB {
      from {
        transform: translateX(0)
      }

      to {
        transform: translateX(-420px)
      }
    }


    /* ============================= LOGIN ============================= */
    #screen-login {
      position: relative;
      min-height: 100vh;
      background: radial-gradient(1200px 700px at 20% -10%, var(--navy-700) 0%, var(--navy-900) 45%, var(--navy-950) 100%);
      padding: 32px 20px;
    }

    #screen-login.active {
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .login-shell {
      position: relative;
      z-index: 2;
      width: 100%;
      max-width: 960px;
      display: grid;
      grid-template-columns: 1.05fr 1fr;
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      overflow: hidden;
    }

    .login-brand {
      background: linear-gradient(165deg, var(--navy-800) 0%, var(--navy-900) 60%, var(--navy-950) 100%);
      color: #fff;
      padding: 44px 40px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    .login-brand .horizon {
      opacity: .5;
    }

    .brand-top {
      display: flex;
      align-items: center;
      gap: 12px;
      position: relative;
      z-index: 2;
    }

    .emblem {
      width: 52px;
      height: 52px;
      border-radius: 50%;
      background: var(--gold-100);
      display: flex;
      align-items: center;
      justify-content: center;
      border: 2px solid var(--gold-500);
      flex-shrink: 0;
    }

    .emblem svg {
      width: 28px;
      height: 28px;
      stroke: var(--navy-800);
    }

    .brand-top .titles {
      line-height: 1.5;
    }

    .brand-top .titles b {
      display: block;
      font-size: 15px;
      font-weight: 700;
    }

    .brand-top .titles span {
      display: block;
      font-size: 12px;
      color: var(--navy-100);
      opacity: .85;
    }

    .login-brand .headline {
      position: relative;
      z-index: 2;
      margin-top: auto;
      padding-top: 60px;
    }

    .login-brand .headline h1 {
      font-size: 26px;
      line-height: 1.55;
      font-weight: 800;
      margin: 0 0 12px;
    }

    .login-brand .headline p {
      font-size: 13.5px;
      color: var(--navy-100);
      opacity: .9;
      line-height: 2;
      margin: 0;
    }

    .login-brand .stripe {
      position: relative;
      z-index: 2;
      margin-top: 26px;
      display: flex;
      gap: 18px;
      font-size: 12px;
      color: var(--navy-100);
    }

    .login-brand .stripe span {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .login-brand .stripe svg {
      width: 14px;
      height: 14px;
      stroke: var(--gold-500);
    }

    .login-form-wrap {
      padding: 44px 40px;
      display: flex;
      flex-direction: column;
    }

    .login-form-wrap h2 {
      font-size: 20px;
      font-weight: 800;
      margin: 0 0 6px;
      color: var(--navy-900);
    }

    .login-form-wrap .sub {
      font-size: 13px;
      color: var(--ink-500);
      margin: 0 0 28px;
      line-height: 1.9;
    }

    .field {
      margin-bottom: 18px;
    }

    .field label {
      display: block;
      font-size: 13px;
      font-weight: 600;
      color: var(--ink-700);
      margin-bottom: 8px;
    }

    .field .hint {
      font-size: 11.5px;
      color: var(--ink-300);
      margin-top: 6px;
    }

    .field .err {
      font-size: 11.5px;
      color: var(--red-600);
      margin-top: 6px;
      display: none;
      font-weight: 600;
    }

    .field.invalid .err {
      display: block;
    }

    .field.invalid input {
      border-color: var(--red-600);
      background: var(--red-100);
    }

    .input {
      width: 100%;
      padding: 13px 14px;
      border: 1.5px solid var(--border);
      border-radius: var(--radius-sm);
      font-size: 14px;
      color: var(--ink-900);
      background: var(--navy-050);
      transition: border-color .15s, background .15s;
    }

    .input:focus {
      border-color: var(--navy-600);
      background: #fff;
    }

    .input::placeholder {
      color: var(--ink-300);
    }

    .btn {
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      font-weight: 700;
      font-size: 14px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      transition: transform .12s ease, box-shadow .12s ease, background .15s;
    }

    .btn:active {
      transform: translateY(1px);
    }

    .btn-primary {
      background: var(--navy-800);
      color: #fff;
      padding: 14px 18px;
      width: 100%;
      box-shadow: var(--shadow-sm);
    }

    .btn-primary:hover {
      background: var(--navy-700);
      box-shadow: var(--shadow-md);
    }

    .btn-primary svg {
      width: 17px;
      height: 17px;
      stroke: #fff;
    }

    .btn-ghost {
      background: transparent;
      color: var(--navy-700);
      padding: 10px 6px;
      font-size: 13px;
    }

    .btn-ghost:hover {
      text-decoration: underline;
    }

    .legal {
      font-size: 11px;
      color: var(--ink-300);
      text-align: center;
      margin-top: 22px;
      line-height: 1.8;
    }

    .otp-boxes {
      display: flex;
      gap: 10px;
      direction: ltr;
      align-items: center;
      justify-content: center;
      gap: 12px;
    }

    .otp-boxes input {
      width: 52px;
      height: 56px;
      text-align: center;
      font-size: 20px;
      font-weight: 700;
      font-family: var(--font-mono);
      border: 1.5px solid var(--border);
      border-radius: var(--radius-sm);
      background: var(--navy-050);
    }

    .otp-boxes input:focus {
      border-color: var(--navy-600);
      background: #fff;
    }

    .otp-meta {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: 14px;
      font-size: 12.5px;
      color: var(--ink-500);
    }

    .otp-meta b {
      color: var(--navy-700);
      font-family: var(--font-mono);
    }

    .step {
      display: none;
    }

    .step.active {
      display: block;
    }

    .back-link {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12.5px;
      color: var(--ink-500);
      cursor: pointer;
      margin-bottom: 18px;
      width: fit-content;
    }

    .back-link svg {
      width: 14px;
      height: 14px;
    }

    .back-link:hover {
      color: var(--navy-700);
    }

    @media (max-width:760px) {
      .login-shell {
        grid-template-columns: 1fr;
      }

      .login-brand {
        padding: 32px 26px 26px;
      }

      .login-brand .headline {
        padding-top: 26px;
      }

      .login-form-wrap {
        padding: 32px 26px;
      }
    }

    /* ============================= DASHBOARD SHELL ============================= */
    #screen-dashboard {
      background: var(--navy-050);
      min-height: 100vh;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 40;
      background: var(--white);
      border-bottom: 1px solid var(--border);
    }

    .topbar-inner {
      max-width: 1440px;
      margin: 0 auto;
      padding: 12px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .topbar-brand {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .topbar-brand .emblem {
      width: 42px;
      height: 42px;
    }

    .topbar-brand .emblem svg {
      width: 22px;
      height: 22px;
    }

    .topbar-brand .titles b {
      font-size: 14.5px;
      color: var(--navy-900);
      display: block;
      font-weight: 800;
    }

    .topbar-brand .titles span {
      font-size: 11.5px;
      color: var(--ink-500);
    }

    .topbar-actions {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .icon-btn {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      position: relative;
      color: var(--ink-700);
      transition: background .15s, border-color .15s;
    }

    .icon-btn:hover {
      background: var(--navy-100);
      border-color: var(--navy-100);
    }

    .icon-btn svg {
      width: 19px;
      height: 19px;
    }

    .badge-dot {
      position: absolute;
      top: -2px;
      left: -2px;
      min-width: 16px;
      height: 16px;
      border-radius: 50%;
      background: var(--red-600);
      color: #fff;
      font-size: 9.5px;
      font-family: var(--font-mono);
      display: flex;
      align-items: center;
      justify-content: center;
      border: 2px solid #fff;
      font-weight: 700;
    }

    .user-chip {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 6px 6px 6px 14px;
      border: 1px solid var(--border);
      border-radius: 999px;
      cursor: pointer;
      background: var(--white);
      position: relative;
    }

    .user-chip:hover {
      background: var(--navy-100);
    }

    .user-chip .avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--navy-800);
      color: #fff;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12.5px;
      font-weight: 700;
      flex-shrink: 0;
    }

    .user-chip .who {
      line-height: 1.4;
    }

    .user-chip .who b {
      display: block;
      font-size: 12.5px;
      color: var(--ink-900);
    }

    .user-chip .who span {
      font-size: 10.5px;
      color: var(--ink-500);
      font-family: var(--font-mono);
      direction: ltr;
      display: block;
      text-align: right;
    }

    .user-chip svg.chev {
      width: 14px;
      height: 14px;
      color: var(--ink-500);
    }

    .dropdown {
      position: absolute;
      top: calc(100% + 8px);
      inset-inline-end: 0;
      min-width: 230px;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 8px;
      display: none;
      z-index: 60;
    }

    .dropdown.open {
      display: block;
    }

    .dropdown .dd-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      border-radius: 10px;
      cursor: pointer;
      font-size: 13px;
      color: var(--ink-700);
    }

    .dropdown .dd-item:hover {
      background: var(--navy-100);
    }

    .dropdown .dd-item svg {
      width: 16px;
      height: 16px;
      color: var(--navy-700);
      flex-shrink: 0;
    }

    .dropdown .dd-item.danger {
      color: var(--red-600);
    }

    .dropdown .dd-item.danger svg {
      color: var(--red-600);
    }

    .dropdown hr {
      border: none;
      border-top: 1px solid var(--border-soft);
      margin: 6px 4px;
    }

    .notif-item {
      padding: 11px 12px;
      border-radius: 10px;
    }

    .notif-item:hover {
      background: var(--navy-100);
    }

    .notif-item b {
      display: block;
      font-size: 12.5px;
      color: var(--ink-900);
      margin-bottom: 3px;
    }

    .notif-item span {
      font-size: 11px;
      color: var(--ink-500);
    }

    .dropdown.wide {
      min-width: 300px;
    }

    .dd-title {
      font-size: 12px;
      font-weight: 700;
      color: var(--ink-500);
      padding: 6px 12px 8px;
    }

    /* ============================= LAYOUT: sidebar + content ============================= */
    .dash-main {
      max-width: 1440px;
      margin: 0 auto;
      padding: 24px;
      display: grid;
      grid-template-columns: 276px 1fr;
      gap: 20px;
      align-items: start;
    }

    .sidebar {
      position: sticky;
      top: 88px;
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-sm);
      padding: 14px;
      max-height: calc(100vh - 108px);
      overflow-y: auto;
    }

    .nav-group {
      margin-bottom: 4px;
    }

    .nav-group-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px 12px 6px;
      cursor: pointer;
      user-select: none;
    }

    .nav-group-head span {
      font-size: 11px;
      color: var(--ink-300);
      font-weight: 700;
      letter-spacing: .02em;
    }

    .nav-group-head .grp-chev {
      width: 13px;
      height: 13px;
      color: var(--ink-300);
      transition: transform .2s;
      flex-shrink: 0;
    }

    .nav-group.open .nav-group-head .grp-chev {
      transform: rotate(180deg);
    }

    .nav-group-body {
      max-height: 0;
      overflow: hidden;
      transition: max-height .25s ease;
    }

    .nav-group.open .nav-group-body {
      max-height: 400px;
    }

    .nav-item {
      display: flex;
      align-items: center;
      gap: 11px;
      padding: 11px 12px;
      border-radius: 12px;
      cursor: pointer;
      font-size: 13.5px;
      font-weight: 600;
      color: var(--ink-700);
      margin-bottom: 2px;
      transition: background .15s, color .15s;
    }

    .nav-item svg {
      width: 18px;
      height: 18px;
      flex-shrink: 0;
      color: var(--ink-500);
      transition: color .15s;
    }

    .nav-item:hover {
      background: var(--navy-100);
    }

    .nav-item.active {
      background: var(--navy-800);
      color: #fff;
      box-shadow: var(--shadow-sm);
    }

    .nav-item.active svg {
      color: #fff;
    }

    .nav-item .nav-count {
      margin-inline-start: auto;
      background: var(--navy-100);
      color: var(--navy-800);
      font-size: 10.5px;
      font-family: var(--font-mono);
      padding: 2px 7px;
      border-radius: 999px;
      font-weight: 700;
    }

    .nav-item.active .nav-count {
      background: rgba(255, 255, 255, .22);
      color: #fff;
    }

    .nav-item.danger {
      color: var(--red-600);
    }

    .nav-item.danger svg {
      color: var(--red-600);
    }

    .nav-item.danger:hover {
      background: var(--red-100);
    }

    .side-divider {
      height: 1px;
      background: var(--border-soft);
      margin: 10px 4px;
    }

    .sidebar-cta {
      margin-top: 10px;
      padding: 16px 14px;
      border-radius: var(--radius-sm);
      background: linear-gradient(150deg, var(--navy-800), var(--navy-950));
      color: #fff;
    }

    .sidebar-cta p {
      font-size: 12px;
      line-height: 1.8;
      margin: 0 0 10px;
      color: var(--navy-100);
    }

    .sidebar-cta button {
      width: 100%;
      background: var(--gold-500);
      color: var(--navy-950);
      padding: 10px;
      font-size: 12.5px;
      border-radius: 9px;
    }

    .sidebar-cta button:hover {
      background: #dcb534;
    }

    .content {
      min-width: 0;
    }

    .view {
      display: none;
    }

    .view.active {
      display: block;
      animation: fadeIn .25s ease;
    }

    @keyframes fadeIn {
      from {
        opacity: 0;
        transform: translateY(4px)
      }

      to {
        opacity: 1;
        transform: translateY(0)
      }
    }

    .view-head {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 18px;
      flex-wrap: wrap;
      gap: 10px;
    }

    .view-head h1 {
      font-size: 21px;
      font-weight: 800;
      margin: 0 0 4px;
      color: var(--navy-900);
    }

    .view-head p {
      font-size: 13px;
      color: var(--ink-500);
      margin: 0;
    }

    .greeting-pill {
      font-size: 11.5px;
      color: var(--navy-700);
      background: var(--navy-100);
      padding: 6px 12px;
      border-radius: 999px;
      font-weight: 600;
    }

    /* card grid */
    .grid-3 {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-bottom: 18px;
    }

    .grid-2 {
      display: grid;
      grid-template-columns: 1.3fr 1fr;
      gap: 16px;
    }

    .card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 18px 20px;
      box-shadow: var(--shadow-sm);
    }

    .card-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 1px solid var(--border-soft);
      padding-bottom: 12px;
      margin-bottom: 14px;
    }

    .card-head h3 {
      font-size: 14.5px;
      font-weight: 700;
      margin: 0;
      color: var(--navy-900);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .card-head h3 svg {
      width: 17px;
      height: 17px;
      color: var(--navy-700);
    }

    .card-head a {
      font-size: 12px;
      color: var(--navy-600);
      font-weight: 600;
      cursor: pointer;
    }

    .card-head a:hover {
      text-decoration: underline;
    }

    .stat-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 9px 0;
    }

    .stat-row span {
      font-size: 13px;
      color: var(--ink-700);
    }

    .stat-row b {
      font-size: 19px;
      font-family: var(--font-mono);
      color: var(--navy-900);
    }

    .stat-row b.neg {
      color: var(--red-600);
    }

    .stat-row b.pos {
      color: var(--green-600);
    }

    .stat-row+.stat-row {
      border-top: 1px dashed var(--border-soft);
    }

    .quick-actions {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-bottom: 18px;
    }

    .qa-btn {
      display: flex;
      align-items: center;
      gap: 9px;
      background: #fff;
      border: 1px solid var(--border);
      padding: 11px 16px;
      border-radius: 12px;
      font-size: 13px;
      font-weight: 700;
      color: var(--navy-800);
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .qa-btn svg {
      width: 17px;
      height: 17px;
      color: var(--navy-700);
    }

    .qa-btn:hover {
      border-color: var(--navy-600);
      background: var(--navy-100);
    }

    .qa-btn.primary {
      background: var(--navy-800);
      color: #fff;
    }

    .qa-btn.primary svg {
      color: #fff;
    }

    .qa-btn.primary:hover {
      background: var(--navy-700);
    }

    /* progress ring */
    .ring-wrap {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .ring {
      width: 96px;
      height: 96px;
      position: relative;
      flex-shrink: 0;
    }

    .ring svg {
      transform: rotate(-90deg);
    }

    .ring .bg {
      stroke: var(--navy-100);
    }

    .ring .fg {
      stroke: var(--navy-700);
      stroke-linecap: round;
      transition: stroke-dashoffset 1s ease;
    }

    .ring-label {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    .ring-label b {
      font-size: 16px;
      font-family: var(--font-mono);
      color: var(--navy-900);
    }

    .ring-label span {
      font-size: 9.5px;
      color: var(--ink-500);
    }

    .ring-info b {
      display: block;
      font-size: 13.5px;
      color: var(--ink-900);
      margin-bottom: 4px;
    }

    .ring-info span {
      font-size: 12px;
      color: var(--ink-500);
      line-height: 1.7;
    }

    .ring-info .status-badge {
      margin-top: 8px;
    }

    .list-item {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 12px 0;
    }

    .list-item+.list-item {
      border-top: 1px solid var(--border-soft);
    }

    .list-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--navy-600);
      margin-top: 6px;
      flex-shrink: 0;
    }

    .list-item .li-title {
      font-size: 13px;
      font-weight: 700;
      color: var(--ink-900);
      margin-bottom: 3px;
    }

    .list-item .li-sub {
      font-size: 11.5px;
      color: var(--ink-500);
    }

    .li-date {
      font-size: 10.5px;
      color: var(--ink-300);
      font-family: var(--font-mono);
      white-space: nowrap;
    }

    .status-badge {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-size: 11px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 999px;
    }

    .status-badge svg {
      width: 11px;
      height: 11px;
    }

    .status-review {
      background: var(--amber-100);
      color: var(--amber-600);
    }

    .status-referred {
      background: var(--navy-100);
      color: var(--navy-700);
    }

    .status-resolved {
      background: var(--green-100);
      color: var(--green-600);
    }

    .status-rejected {
      background: var(--red-100);
      color: var(--red-600);
    }

    /* ---- report form ---- */
    .cat-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-bottom: 22px;
    }

    .cat-card {
      border: 1.5px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 16px 12px;
      text-align: center;
      cursor: pointer;
      background: #fff;
      transition: border-color .15s, background .15s, transform .1s;
    }

    .cat-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-sm);
    }

    .cat-card .cico {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: var(--navy-100);
      margin: 0 auto 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .cat-card .cico svg {
      width: 22px;
      height: 22px;
      color: var(--navy-700);
    }

    .cat-card span {
      font-size: 12px;
      font-weight: 700;
      color: var(--ink-700);
    }

    .cat-card.selected {
      border-color: var(--navy-700);
      background: var(--navy-100);
    }

    .cat-card.selected .cico {
      background: var(--navy-800);
    }

    .cat-card.selected .cico svg {
      color: #fff;
    }

    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .form-grid .full {
      grid-column: 1/-1;
    }

    textarea.input {
      resize: vertical;
      min-height: 110px;
      line-height: 1.9;
    }

    .seg {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }

    .seg-opt {
      padding: 9px 16px;
      border: 1.5px solid var(--border);
      border-radius: 999px;
      font-size: 12.5px;
      font-weight: 700;
      cursor: pointer;
      color: var(--ink-700);
      background: #fff;
    }

    .seg-opt.urgent {
      color: var(--red-600);
    }

    .seg-opt.selected {
      background: var(--navy-800);
      border-color: var(--navy-800);
      color: #fff;
    }

    .seg-opt.urgent.selected {
      background: var(--red-600);
      border-color: var(--red-600);
    }

    .upload-box {
      border: 1.5px dashed var(--border);
      border-radius: var(--radius-sm);
      padding: 26px;
      text-align: center;
      color: var(--ink-500);
      font-size: 12.5px;
      cursor: pointer;
      background: var(--navy-050);
    }

    .upload-box svg {
      width: 26px;
      height: 26px;
      color: var(--navy-500);
      margin-bottom: 8px;
    }

    .upload-box b {
      color: var(--navy-700);
    }

    .form-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 20px;
    }

    .btn-secondary {
      background: #fff;
      border: 1.5px solid var(--border);
      color: var(--ink-700);
      padding: 12px 20px;
    }

    .btn-secondary:hover {
      background: var(--navy-100);
    }

    .btn-submit {
      background: var(--navy-800);
      color: #fff;
      padding: 12px 26px;
    }

    .btn-submit:hover {
      background: var(--navy-700);
    }

    .btn-submit svg {
      width: 16px;
      height: 16px;
      stroke: #fff;
    }

    /* ---- tracking table ---- */
    .filter-row {
      display: flex;
      gap: 8px;
      margin-bottom: 16px;
      flex-wrap: wrap;
    }

    .filter-chip {
      padding: 8px 15px;
      border-radius: 999px;
      border: 1.5px solid var(--border);
      font-size: 12px;
      font-weight: 700;
      color: var(--ink-500);
      cursor: pointer;
      background: #fff;
    }

    .filter-chip.active {
      background: var(--navy-800);
      border-color: var(--navy-800);
      color: #fff;
    }

    .report-card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 16px 18px;
      margin-bottom: 12px;
      box-shadow: var(--shadow-sm);
      cursor: pointer;
      transition: box-shadow .15s;
    }

    .report-card:hover {
      box-shadow: var(--shadow-md);
    }

    .report-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 10px;
    }

    .report-id {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--ink-300);
    }

    .report-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--ink-900);
      margin-bottom: 6px;
    }

    .report-meta {
      display: flex;
      gap: 14px;
      font-size: 11.5px;
      color: var(--ink-500);
      flex-wrap: wrap;
    }

    .report-meta span {
      display: flex;
      align-items: center;
      gap: 5px;
    }

    .report-meta svg {
      width: 13px;
      height: 13px;
    }

    .report-detail {
      display: none;
      margin-top: 14px;
      padding-top: 14px;
      border-top: 1px dashed var(--border);
    }

    .report-card.open .report-detail {
      display: block;
    }

    .timeline {
      display: flex;
      flex-direction: column;
      gap: 0;
    }

    .tl-item {
      display: flex;
      gap: 12px;
      padding-bottom: 16px;
      position: relative;
    }

    .tl-item:last-child {
      padding-bottom: 0;
    }

    .tl-item::before {
      content: '';
      position: absolute;
      right: 5px;
      top: 16px;
      bottom: 0;
      width: 1.5px;
      background: var(--border);
    }

    .tl-item:last-child::before {
      display: none;
    }

    .tl-dot {
      width: 11px;
      height: 11px;
      border-radius: 50%;
      background: var(--navy-700);
      flex-shrink: 0;
      margin-top: 3px;
      z-index: 1;
      border: 2px solid #fff;
      box-shadow: 0 0 0 1px var(--border);
    }

    .tl-dot.done {
      background: var(--green-600);
    }

    .tl-body b {
      font-size: 12.5px;
      color: var(--ink-900);
      display: block;
    }

    .tl-body span {
      font-size: 11px;
      color: var(--ink-500);
    }

    .empty-state {
      text-align: center;
      padding: 50px 20px;
      color: var(--ink-500);
    }

    .empty-state svg {
      width: 46px;
      height: 46px;
      color: var(--navy-100);
      margin-bottom: 14px;
    }

    .empty-state p {
      font-size: 13px;
      margin: 0;
    }

    /* ---- governor contact ---- */
    .gov-card {
      display: flex;
      gap: 16px;
      align-items: center;
      padding-bottom: 16px;
      margin-bottom: 16px;
      border-bottom: 1px solid var(--border-soft);
    }

    .gov-photo {
      width: 64px;
      height: 64px;
      border-radius: 50%;
      background: var(--navy-100);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      border: 2px solid var(--navy-100);
    }

    .gov-photo svg {
      width: 30px;
      height: 30px;
      color: var(--navy-700);
    }

    .gov-info b {
      font-size: 14.5px;
      display: block;
      color: var(--navy-900);
    }

    .gov-info span {
      font-size: 12px;
      color: var(--ink-500);
    }

    .info-line {
      display: flex;
      align-items: center;
      gap: 9px;
      font-size: 12.5px;
      color: var(--ink-700);
      padding: 7px 0;
    }

    .info-line svg {
      width: 15px;
      height: 15px;
      color: var(--navy-600);
      flex-shrink: 0;
    }

    /* ---- news / faq ---- */
    .news-card {
      display: flex;
      gap: 14px;
      padding: 15px 0;
      border-bottom: 1px solid var(--border-soft);
    }

    .news-card:last-child {
      border-bottom: none;
    }

    .news-icon {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: var(--navy-100);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .news-icon svg {
      width: 20px;
      height: 20px;
      color: var(--navy-700);
    }

    .news-tag {
      display: inline-block;
      font-size: 10px;
      font-weight: 700;
      color: var(--navy-700);
      background: var(--navy-100);
      padding: 3px 9px;
      border-radius: 999px;
      margin-bottom: 6px;
    }

    .news-card h4 {
      font-size: 13.5px;
      margin: 0 0 5px;
      color: var(--ink-900);
    }

    .news-card p {
      font-size: 12px;
      color: var(--ink-500);
      margin: 0;
      line-height: 1.8;
    }

    .faq-item {
      border-bottom: 1px solid var(--border-soft);
    }

    .faq-q {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 4px;
      cursor: pointer;
      font-size: 13.5px;
      font-weight: 700;
      color: var(--ink-900);
    }

    .faq-q svg {
      width: 16px;
      height: 16px;
      color: var(--navy-600);
      transition: transform .2s;
      flex-shrink: 0;
    }

    .faq-item.open .faq-q svg {
      transform: rotate(180deg);
    }

    .faq-a {
      display: none;
      padding: 0 4px 16px;
      font-size: 12.5px;
      color: var(--ink-500);
      line-height: 1.9;
    }

    .faq-item.open .faq-a {
      display: block;
    }

    /* ---- directory ---- */
    .dir-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }

    .dir-card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 16px;
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .dir-card .dico {
      width: 42px;
      height: 42px;
      border-radius: 10px;
      background: var(--red-100);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .dir-card.util .dico {
      background: var(--navy-100);
    }

    .dir-card .dico svg {
      width: 20px;
      height: 20px;
      color: var(--red-600);
    }

    .dir-card.util .dico svg {
      color: var(--navy-700);
    }

    .dir-card b {
      display: block;
      font-size: 12.5px;
      color: var(--ink-900);
      margin-bottom: 3px;
    }

    .dir-card .num {
      font-size: 14px;
      font-weight: 800;
      color: var(--navy-800);
    }

    /* ---- poll ---- */
    .poll-opt {
      border: 1.5px solid var(--border);
      border-radius: 12px;
      padding: 13px 15px;
      margin-bottom: 10px;
      cursor: pointer;
      position: relative;
      overflow: hidden;
    }

    .poll-opt:hover {
      border-color: var(--navy-500);
    }

    .poll-fill {
      position: absolute;
      inset-inline-start: 0;
      top: 0;
      bottom: 0;
      background: var(--navy-100);
      width: 0%;
      transition: width 1s ease;
      z-index: 0;
    }

    .poll-opt-inner {
      position: relative;
      z-index: 1;
      display: flex;
      justify-content: space-between;
      font-size: 13px;
      font-weight: 600;
      color: var(--ink-800);
    }

    .poll-opt .pct {
      font-family: var(--font-mono);
      color: var(--navy-700);
      font-weight: 700;
      display: none;
    }

    .poll-opt.voted .pct {
      display: inline;
    }

    .poll-opt.chosen {
      border-color: var(--navy-800);
    }

    .poll-note {
      font-size: 11.5px;
      color: var(--ink-500);
      margin-top: 10px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .poll-note svg {
      width: 14px;
      height: 14px;
      color: var(--green-600);
    }

    /* ---- profile ---- */
    .profile-head {
      display: flex;
      align-items: center;
      gap: 16px;
      margin-bottom: 22px;
      padding-bottom: 20px;
      border-bottom: 1px solid var(--border-soft);
    }

    .profile-avatar {
      width: 76px;
      height: 76px;
      border-radius: 50%;
      background: var(--navy-800);
      color: #fff;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 26px;
      font-weight: 700;
    }

    .profile-head h3 {
      margin: 0 0 4px;
      font-size: 16px;
      color: var(--navy-900);
    }

    .profile-head span {
      font-size: 12px;
      color: var(--ink-500);
    }

    .verified-chip {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      background: var(--green-100);
      color: var(--green-600);
      font-size: 11px;
      font-weight: 700;
      padding: 3px 10px;
      border-radius: 999px;
      margin-top: 6px;
    }

    .verified-chip svg {
      width: 11px;
      height: 11px;
    }

    /* toast */
    #toast-container {
      position: fixed;
      bottom: 24px;
      inset-inline-end: 24px;
      z-index: 200;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .toast {
      background: var(--navy-900);
      color: #fff;
      padding: 14px 18px;
      border-radius: 12px;
      font-size: 13px;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 10px;
      box-shadow: var(--shadow-lg);
      min-width: 260px;
      animation: slideIn .3s ease;
    }

    .toast.success svg {
      color: #6fdc9c;
    }

    .toast.error svg {
      color: #f18b8b;
    }

    .toast svg {
      width: 18px;
      height: 18px;
      flex-shrink: 0;
    }

    @keyframes slideIn {
      from {
        opacity: 0;
        transform: translateY(10px)
      }

      to {
        opacity: 1;
        transform: translateY(0)
      }
    }

    /* mobile */
    @media (max-width:980px) {
      .dash-main {
        grid-template-columns: 1fr;
      }

      .sidebar {
        position: static;
        max-height: none;
        order: 2;
      }

      .content {
        order: 1;
      }

      .grid-3,
      .form-grid,
      .cat-grid,
      .dir-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .grid-2 {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width:600px) {

      .grid-3,
      .cat-grid,
      .dir-grid,
      .form-grid {
        grid-template-columns: 1fr;
      }

      .topbar-brand .titles span {
        display: none;
      }

      .user-chip .who {
        display: none;
      }
    }

    svg[fill="none"] {
  stroke: currentColor;
}

