 :root {
     --navy: #00477A;
     --navy-dark: #00325a;
     --blue-light: #eaf2f8;
     --text-main: #111827;
     --text-muted: #6b7280;
     --text-faint: #9ca3af;
     --border: #e5e7eb;
     --bg-field: #f8fafc;
     --radius-lg: 22px;
     --radius-md: 14px;
     --radius-sm: 10px;
 }

 * {
     box-sizing: border-box;
 }

 .fb-wrap {
     max-width: 83%;
     margin: 0 auto;
     padding-inline: 20px;
 }

 /* ---------- کارت اصلی ---------- */
 .fb-card {
     background: #fff;
     border-radius: 2px 2px 15px 15px;
     box-shadow: 0 30px 70px -25px rgba(15, 40, 70, 0.18), 0 2px 8px rgba(15, 40, 70, 0.04);
     display: grid;
     grid-template-columns: 1fr 320px;
     overflow: hidden;
 }

 /* ============================================================
ستون فرم
============================================================ */
 .fb-form-col {
     padding: 52px 56px;
 }

 .fb-head {
     margin-bottom: 36px;
 }

 .fb-eyebrow {
     display: inline-flex;
     align-items: center;
     gap: 6px;
     background: var(--blue-light);
     color: var(--navy);
     font-size: 12.5px;
     font-weight: 600;
     padding: 6px 14px;
     border-radius: 20px;
     margin-bottom: 16px;
 }

 .fb-head h1 {
     font-size: 24px;
     line-height: 1.5;
     font-weight: 800;
     color: var(--text-main);
     margin: 0 0 10px;
 }

 .fb-head p {
     font-size: 14px;
     color: var(--text-muted);
     line-height: 1.9;
     margin: 0;
     max-width: 520px;
 }

 .fb-form {
     display: flex;
     flex-direction: column;
     gap: 22px;
 }

 .fb-row {
     display: grid;
     grid-template-columns: 1fr 1fr;
     gap: 22px;
 }

 .fb-field {
     display: flex;
     flex-direction: column;
     gap: 9px;
     position: relative;
 }

 .fb-field label {
     display: flex;
     align-items: center;
     gap: 7px;
     font-size: 13.5px;
     font-weight: 600;
     color: var(--text-main);
 }

 .fb-field label svg {
     width: 16px;
     height: 16px;
     color: var(--navy);
     opacity: .8;
 }

 .fb-field input,
 .fb-field textarea {
     width: 100%;
     border: 1.5px solid var(--border);
     background: var(--bg-field);
     border-radius: var(--radius-sm);
     padding: 14px 16px;
     font-family: inherit;
     font-size: 14px;
     color: var(--text-main);
     outline: none;
     transition: border-color .2s ease, background .2s ease, box-shadow .2s ease;
 }

 .fb-field textarea {
     resize: vertical;
     min-height: 130px;
     line-height: 1.8;
 }

 .fb-field input::placeholder,
 .fb-field textarea::placeholder {
     color: var(--text-faint);
 }

 .fb-field input:hover,
 .fb-field textarea:hover {
     border-color: #cbd5e1;
 }

 .fb-field input:focus,
 .fb-field textarea:focus {
     background: #fff;
     border-color: var(--navy);
     box-shadow: 0 0 0 4px rgba(0, 71, 122, 0.1);
 }

 .fb-counter {
     align-self: flex-start;
     font-size: 11.5px;
     color: var(--text-faint);
 }

 /* ---------- کپچا ---------- */
 .fb-captcha {
     border: 1.5px dashed #d5dce3;
     border-radius: var(--radius-md);
     padding: 16px;
     display: flex;
     flex-direction: column;
     gap: 12px;
     background: #fbfcfd;
 }

 .fb-captcha-top {
     display: flex;
     align-items: center;
     gap: 12px;
 }

 .fb-captcha-img {
     border-radius: var(--radius-sm);
     overflow: hidden;
     line-height: 0;
     border: 1px solid var(--border);
 }

 .fb-captcha-img svg {
     display: block;
     width: 150px;
     height: 52px;
 }

 .fb-captcha-refresh {
     width: 42px;
     height: 42px;
     border-radius: 50%;
     border: 1px solid var(--border);
     background: #fff;
     color: var(--navy);
     display: flex;
     align-items: center;
     justify-content: center;
     cursor: pointer;
     flex-shrink: 0;
     transition: background .2s ease, transform .4s ease, border-color .2s ease;
 }

 .fb-captcha-refresh svg {
     width: 18px;
     height: 18px;
 }

 .fb-captcha-refresh:hover {
     background: var(--blue-light);
     border-color: var(--navy);
 }

 .fb-captcha-refresh:active svg {
     transform: rotate(180deg);
 }

 .fb-captcha-input {
     width: 100%;
     max-width: 260px;
     border: 1.5px solid var(--border);
     background: #fff;
     border-radius: var(--radius-sm);
     padding: 11px 14px;
     font-family: inherit;
     font-size: 13.5px;
     outline: none;
     transition: border-color .2s ease, box-shadow .2s ease;
 }

 .fb-captcha-input:focus {
     border-color: var(--navy);
     box-shadow: 0 0 0 4px rgba(0, 71, 122, 0.1);
 }

 /* ---------- دکمه‌ی ارسال ---------- */
 .fb-submit {
     display: flex;
     align-items: center;
     justify-content: center;
     gap: 10px;
     border: none;
     background: linear-gradient(135deg, #00609c, var(--navy-dark));
     color: #fff;
     font-family: inherit;
     font-size: 15px;
     font-weight: 700;
     padding: 16px 24px;
     border-radius: var(--radius-sm);
     cursor: pointer;
     margin-top: 4px;
     box-shadow: 0 14px 28px -10px rgba(0, 71, 122, 0.45);
     transition: transform .2s ease, box-shadow .2s ease, filter .2s ease;
 }

 .fb-submit svg {
     width: 18px;
     height: 18px;
     transform: rotate(90deg);
 }

 .fb-submit:hover {
     transform: translateY(-2px);
     box-shadow: 0 18px 34px -10px rgba(0, 71, 122, 0.55);
     filter: brightness(1.05);
 }

 .fb-submit:active {
     transform: translateY(0);
 }

 /* ============================================================
ستون پروفایل استاندار
============================================================ */
 .fb-profile-col {
     background: linear-gradient(180deg, #f4f8fb 0%, #eef3f7 100%);
     border-right: 1px solid #eef1f4;
     padding: 52px 30px;
     display: flex;
     flex-direction: column;
     align-items: center;
     justify-content: flex-start;
     gap: 22px;
     text-align: center;
 }

 .fb-profile-card {
     display: flex;
     flex-direction: column;
     align-items: center;
     width: 100%;
 }

 .fb-profile-photo {
     width: 128px;
     height: 128px;
     border-radius: 50%;
     padding: 5px;
     background: linear-gradient(135deg, #00609c, var(--navy));
     margin-bottom: 18px;
 }

 .fb-profile-photo img {
     width: 100%;
     height: 100%;
     object-fit: cover;
     border-radius: 50%;
     border: 3px solid #fff;
     display: block;
 }

 .fb-photo-fallback {
     display: flex;
     align-items: center;
     justify-content: center;
 }

 .fb-profile-card h3 {
     font-size: 17px;
     font-weight: 800;
     color: var(--text-main);
     margin: 0 0 6px;
 }

 .fb-profile-role {
     display: inline-block;
     font-size: 12.5px;
     font-weight: 600;
     color: var(--navy);
     background: #fff;
     padding: 5px 14px;
     border-radius: 20px;
     border: 1px solid #dfe8ef;
 }

 .fb-profile-divider {
     width: 46px;
     height: 3px;
     border-radius: 3px;
     background: linear-gradient(90deg, #00609c, var(--navy));
     margin: 22px 0;
 }

 .fb-profile-contacts {
     display: flex;
     align-items: center;
     justify-content: center;
     gap: 12px;
 }

 .fb-contact-btn {
     width: 42px;
     height: 42px;
     border-radius: 50%;
     background: #fff;
     border: 1px solid #dfe8ef;
     color: var(--navy);
     display: flex;
     align-items: center;
     justify-content: center;
     text-decoration: none;
     position: relative;
     transition: background .2s ease, color .2s ease, transform .2s ease, box-shadow .2s ease;
 }

 .fb-contact-btn svg {
     width: 17px;
     height: 17px;
 }

 .fb-contact-btn:hover {
     background: var(--navy);
     color: #fff;
     transform: translateY(-3px);
     box-shadow: 0 10px 20px -8px rgba(0, 71, 122, 0.5);
 }

 .fb-contact-btn::after {
     content: attr(data-tip);
     position: absolute;
     bottom: calc(100% + 8px);
     left: 50%;
     transform: translateX(-50%) translateY(4px);
     background: var(--text-main);
     color: #fff;
     font-size: 11px;
     padding: 4px 9px;
     border-radius: 6px;
     white-space: nowrap;
     opacity: 0;
     pointer-events: none;
     transition: opacity .2s ease, transform .2s ease;
 }

 .fb-contact-btn:hover::after {
     opacity: 1;
     transform: translateX(-50%) translateY(0);
 }

 .fb-note {
     display: flex;
     align-items: flex-start;
     gap: 8px;
     background: #fff;
     border: 1px solid #dfe8ef;
     border-radius: var(--radius-md);
     padding: 14px 16px;
     text-align: right;
 }

 .fb-note svg {
     width: 17px;
     height: 17px;
     color: var(--navy);
     flex-shrink: 0;
     margin-top: 2px;
 }

 .fb-note p {
     margin: 0;
     font-size: 12px;
     color: var(--text-muted);
     line-height: 1.8;
 }

 /* ============================================================
واکنش‌گرا
============================================================ */
 @media (max-width: 900px) {
     .fb-card {
         grid-template-columns: 1fr;
         border-radius: 15px;
     }

     .fb-wrap{
         padding: 0;
     padding-top: 20px;
     }

     .fb-profile-col {
         border-right: none;
         border-top: 1px solid #eef1f4;
         order: -1;
         flex-direction: row;
         flex-wrap: wrap;
         justify-content: space-between;
         text-align: right;
         padding: 30px 28px;
     }

     .fb-profile-card {
         flex-direction: row;
         align-items: center;
         text-align: right;
         width: auto;
         gap: 16px;
     }

     .fb-profile-photo {
         width: 84px;
         height: 84px;
         margin-bottom: 0;
     }

     .fb-profile-divider {
         display: none;
     }

     .fb-note {
         display: none;
     }
 }

 @media (max-width: 640px) {
     body {
         padding: 24px 12px;
     }

     .fb-form-col {
         padding: 34px 22px;
     }

     .fb-head h1 {
         font-size: 20px;
     }

     .fb-row {
         grid-template-columns: 1fr;
         gap: 18px;
     }

     .fb-profile-col {
         flex-direction: column;
         text-align: center;
         gap: 16px;
     }

     .fb-profile-card {
         flex-direction: column;
         text-align: center;
     }

     .fb-captcha-input {
         max-width: 100%;
     }
 }

body {
    background: #E4E6ED;
    margin: 0;
    padding: 40px 0;
}

.gal-wrap {
    width: 92%;
    max-width: 1280px;
    margin: 0 auto;
}

/* ===== عنوان بخش ===== */
.gal-head {
    text-align: center;
    margin-bottom: 34px;
}

.gal-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(0, 71, 122, 0.08);
    color: #00477A;
    font-size: 12px;
    font-weight: 600;
    padding: 6px 16px;
    border-radius: 20px;
    margin-bottom: 16px;
}

.gal-head h2 {
    font-size: 26px;
    font-weight: 700;
    color: #00477A;
    margin: 0 0 10px;
}

.gal-head p {
    font-size: 13.5px;
    color: #6B7280;
    max-width: 560px;
    margin: 0 auto;
    line-height: 1.9;
}

.gal-rule {
    width: 56px;
    height: 4px;
    border-radius: 4px;
    background: linear-gradient(90deg, #00477A, #4789BB);
    margin: 18px auto 0;
}

/* ===== فیلترها ===== */
.gal-filters {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 30px;
}

.gal-filter-btn {
    border: 1px solid rgba(0, 71, 122, 0.18);
    background: #FFFFFF;
    color: #34495e;
    font-size: 12.5px;
    font-weight: 600;
    padding: 8px 20px;
    border-radius: 20px;
    cursor: pointer;
    transition: .25s;
}

.gal-filter-btn:hover {
    border-color: #00477A;
    color: #00477A;
}

.gal-filter-btn.active {
    background: #00477A;
    border-color: #00477A;
    color: #fff;
}

/* ===== گرید گالری ===== */
.gal-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 22px;
}

.gal-item {
    position: relative;
    border-radius: 14px;
    overflow: hidden;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
    cursor: pointer;
    transition: transform .3s ease, box-shadow .3s ease;
}

.gal-item:hover {
    transform: translateY(-6px);
    box-shadow: 0 16px 32px rgba(0, 0, 0, 0.13);
}

.gal-media {
    position: relative;
    height: 230px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.gal-media img , .gol-media svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform .45s ease;
}

.gal-item:hover .gal-media img {
    transform: scale(1.08);
}

.gal-media i {
    font-size: 34px;
    color: rgba(255, 255, 255, 0.85);
}

.gal-tag {
    position: absolute;
    top: 12px;
    right: 12px;
    background: rgba(255, 255, 255, 0.92);
    color: #00477A;
    font-size: 10.5px;
    font-weight: 700;
    padding: 5px 12px;
    border-radius: 20px;
    z-index: 2;
}

.gal-zoom {
    position: absolute;
    top: 12px;
    left: 12px;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.92);
    color: #00477A;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    z-index: 2;
    opacity: 0;
    transition: .25s;
}

.gal-item:hover .gal-zoom {
    opacity: 1;
}

.gal-caption {
    position: absolute;
    bottom: 0;
    right: 0;
    left: 0;
    background: linear-gradient(to top, rgba(0, 20, 40, 0.82), rgba(0, 20, 40, 0));
    color: #fff;
    font-size: 12.5px;
    line-height: 1.7;
    padding: 34px 14px 12px;
}

/* رنگ‌های پس‌زمینه نمونه (جایگزین تصویر واقعی) */
.gal-media.tone-1 { background: linear-gradient(150deg, #00477A, #145a94); }
.gal-media.tone-2 { background: linear-gradient(150deg, #0b3c74, #4789BB); }
.gal-media.tone-3 { background: linear-gradient(150deg, #1f4f8a, #2f6690); }

/* ===== کارت مشاهده آرشیو ===== */
.gal-more {
    border: 2px dashed rgba(0, 71, 122, 0.35);
    background: #f7fbff;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 230px;
    transition: .25s;
}

.gal-more:hover {
    background: #00477A;
}

.gal-more i {
    font-size: 26px;
    color: #00477A;
    transition: .25s;
}

.gal-more h3 {
    font-size: 14.5px;
    font-weight: 700;
    color: #16324a;
    margin: 0;
    transition: .25s;
}

.gal-more p {
    font-size: 12px;
    color: #7c8a97;
    margin: 0;
    transition: .25s;
}

.gal-more:hover i,
.gal-more:hover h3,
.gal-more:hover p {
    color: #fff;
}

/* ===== لایت‌باکس ===== */
.lightbox-overlay {
    position: fixed;
    inset: 0;
    background: rgba(10, 20, 35, 0.88);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 999;
    padding: 30px;
}

.lightbox-overlay.active {
    display: flex;
}

.lightbox-box {
    width: 100%;
    max-width: 720px;
    background: #fff;
    border-radius: 16px;
    overflow: hidden;
    position: relative;
}

.lightbox-media {
    height: 420px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.lightbox-media i {
    font-size: 46px;
    color: rgba(255, 255, 255, 0.85);
}

.lightbox-info {
    padding: 18px 22px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.lightbox-info p {
    margin: 0;
    font-size: 13.5px;
    color: #16324a;
    line-height: 1.8;
}

.lightbox-tag {
    display: inline-block;
    background: rgba(71, 137, 187, 0.14);
    color: #2f6690;
    font-size: 11px;
    font-weight: 600;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 8px;
    white-space: nowrap;
}

.lightbox-close {
    position: absolute;
    top: 14px;
    left: 14px;
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.9);
    color: #16324a;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 15px;
    z-index: 2;
}

.lightbox-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.9);
    color: #00477A;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 17px;
    z-index: 2;
    transition: .2s;
}

.lightbox-nav:hover {
    background: #00477A;
    color: #fff;
}

.lightbox-prev { right: 14px; }
.lightbox-next { left: 14px; }

@media (max-width: 1024px) {
    .gal-grid {
        grid-template-columns: repeat(2, 1fr);
