.qs-map-section {
    width: 92%;
    padding: 35px 4% 35px;
    background: #FFFFFF;
    position: relative;
    overflow: hidden;
    box-sizing: border-box;
    border-radius: 15px;
    margin: 30px auto 0 auto;
    box-shadow: 0 4px 9px lightgray;
}

.qs-map-section::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 90% -10%, rgba(45, 156, 219, .45), transparent 55%);
    pointer-events: none;
}

.qs-map-section::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
}

.qs-map-inner {
    max-width: 1280px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 60px;
    position: relative;
    z-index: 1;
    flex-wrap: wrap;
}

.qs-map-text {
    flex: 1 1 380px;
    min-width: 300px;
}

.qs-map-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(15, 62, 145, 0.08);
    border: 1px solid rgba(15, 62, 145, 0.2);
    color: #0F3E91;
    font-size: 13px;
    padding: 6px 16px;
    border-radius: 50px;
    margin-bottom: 22px;
    font-weight: 600;
}

.qs-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--blue-2);
    box-shadow: 0 0 8px 2px rgba(45, 156, 219, 0.9);
    animation: qsPulse 1.6s infinite;
}

@keyframes qsPulse {

    0%,
    100% {
        opacity: 1;
        transform: scale(1);
    }

    50% {
        opacity: 0.4;
        transform: scale(1.5);
    }
}

.qs-map-title {
    color: #0a2a5e;
    font-size: 38px;
    font-weight: 800;
    margin: 0 0 18px;
    line-height: 1.4;
}

.qs-map-title span {
    background: linear-gradient(135deg, #FF8A3D, #FF6B00);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    display: inline-block;
}

.qs-map-desc {
    color: rgb(10 53 124);
    font-size: 16px;
    line-height: 2;
    margin-bottom: 30px;
    max-width: 480px;
}

.qs-map-coords {
    display: flex;
    align-items: center;
    gap: 22px;
    background: #f7f9fc;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    padding: 16px 22px;
    margin-bottom: 30px;
    width: fit-content;
}

.qs-coord-item {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.qs-coord-label {
    color: rgb(10 53 124);
    font-size: 12px;
}

.qs-coord-value {
    color: #7a5f23;
    font-size: 16px;
    font-weight: 700;
    direction: ltr;
    font-family: 'Courier New', monospace;
}

.qs-coord-sep {
    width: 1px;
    height: 34px;
    background: #d7dfe9;
}

.qs-map-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: linear-gradient(135deg, #FF8A3D, #FF6B00);
    color: #fff;
    font-weight: 700;
    font-size: 15px;
    padding: 13px 26px;
    border-radius: 12px;
    text-decoration: none;
    box-shadow: 0 10px 24px rgba(255, 107, 0, 0.35);
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.qs-map-btn:hover {
    transform: translateY(-3px);
    box-shadow: 0 14px 30px rgba(255, 107, 0, 0.45);
}

.qs-map-btn svg {
    transform: rotate(180deg);
}

/* --- تصویر نقشه --- */
.qs-map-visual {
    flex: 1 1 420px;
    min-width: 300px;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
}

.qs-map-glow {
    position: absolute;
    width: 90%;
    height: 90%;
    background: radial-gradient(circle, rgba(45, 156, 219, 0.35) 0%, transparent 70%);
    filter: blur(40px);
    z-index: 0;
    animation: qsGlowMove 6s ease-in-out infinite;
}

@keyframes qsGlowMove {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.7;
    }

    50% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.qs-map-frame {
    position: relative;
    width: 100%;
    /* max-width: 300px; */
    border-radius: var(--radius-lg);
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.25);
    box-shadow:
        0 25px 60px rgba(0, 0, 0, 0.35),
        0 0 0 8px rgba(255, 255, 255, 0.04);
    z-index: 1;
    transform: perspective(900px) rotateY(-4deg) rotateX(2deg);
    transition: transform 0.5s ease;
}

.qs-map-frame:hover {
    transform: perspective(900px) rotateY(0deg) rotateX(0deg) scale(1.02);
}

.qs-map-img {
    width: 100%;
    display: block;
}

.qs-map-shine {
    position: absolute;
    top: 0;
    left: -60%;
    width: 40%;
    height: 100%;
    background: linear-gradient(120deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    transform: skewX(-20deg);
    animation: qsShine 4.5s ease-in-out infinite;
}

@keyframes qsShine {
    0% {
        left: -60%;
    }

    50% {
        left: 130%;
    }

    100% {
        left: 130%;
    }
}

.qs-pin {
    position: absolute;
    top: 46%;
    left: 42%;
    width: 18px;
    height: 18px;
}

.qs-pin-dot {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 12px;
    height: 12px;
    background: #FF6B00;
    border-radius: 50%;
    transform: translate(-50%, -50%);
    box-shadow: 0 0 10px 2px rgba(255, 107, 0, 0.8);
}

.qs-pin-ring {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 100%;
    height: 100%;
    border: 2px solid #FF6B00;
    border-radius: 50%;
    transform: translate(-50%, -50%);
    animation: qsRing 1.8s ease-out infinite;
}

@keyframes qsRing {
    0% {
        transform: translate(-50%, -50%) scale(0.3);
        opacity: 1;
    }

    100% {
        transform: translate(-50%, -50%) scale(2.8);
        opacity: 0;
    }
}

.qs-map-corner {
    position: absolute;
    width: 44px;
    height: 44px;
    border-color: #2D9CDB;
    border-style: solid;
    opacity: 0.8;
    z-index: 0;
}


@media (max-width: 767px) {
    .qs-map-inner {
        flex-direction: column;
        text-align: center;
    }

    .qs-map-coords {
        margin: 0 auto 26px;
    }

    .qs-map-title {
        font-size: 28px;
    }

    .qs-map-desc {
        margin: 0 auto 26px;
    }

    .qs-map-frame {
        transform: none;
    }
}

