:root{
  --navy:#00477A;
  --navy-deep:#003057;
  --blue:#0F3E91;
  --blue-2:#2D9CDB;
  --blue-soft:#EAF2FB;
  --ink:#1F2937;
  --muted:#6B7A8D;
  --line:#E7EDF4;
  --bg:#EEF2F7;
  --radius-xl:22px;
  --radius-lg:16px;
  --radius-md:12px;
  --shadow-1: 0 10px 30px rgba(15,62,145,.08);
  --shadow-2: 0 18px 45px rgba(15,62,145,.14);
}

*{box-sizing:border-box; margin:0; padding:0; font-family:'Vazirmatn', sans-serif;}
body{
  background:var(--bg);
  padding:40px 20px;
  direction:rtl;
}

/* ============ Layout Grid ============ */
.cb2-wrapper{
  max-width:1400px;
  margin:0 auto;
  display:grid;
  grid-template-columns: 300px 1fr 260px;
  gap:22px;
  align-items:start;
}

/* ============ Shared Card ============ */
.cb2-card{
  background:#fff;
  border-radius:15px;
  box-shadow:var(--shadow-1);
  overflow:hidden;
  transition:box-shadow .35s ease, transform .35s ease;
  border:1px solid rgba(15,62,145,.05);
}

.cb2-card-head{
  display:flex;
  align-items:center;
  gap:10px;
  padding:18px 20px;
  background:linear-gradient(120deg, var(--navy) 0%, var(--blue) 100%);
  position:relative;
}
.cb2-card-head::after{
  content:'';
  position:absolute;
  inset:0;
  background:radial-gradient(120px 60px at 90% 0%, rgba(255,255,255,.18), transparent 60%);
  pointer-events:none;
}
.cb2-card-head i{
  width:34px; height:34px;
  background:rgba(255,255,255,.16);
  border-radius:10px;
  display:flex; align-items:center; justify-content:center;
  color:#fff; font-size:15px;
  flex-shrink:0;
}
.cb2-card-head h3{
  color:#fff;
  font-size:15px;
  font-weight:700;
  letter-spacing:.2px;
}

/* ============ LEFT COLUMN: Newsletter + Gallery ============ */
.cb2-left{
  display:flex;
  flex-direction:column;
  gap:22px;
}

.newsletter-body{
  padding:22px 20px 24px;
}
.newsletter-body p{
  font-size:12.5px;
  color:var(--muted);
  line-height:2;
  text-align:justify;
  margin-bottom:16px;
}

.nl-field{
  position:relative;
  margin-bottom:14px;
}
.nl-field i{
  position:absolute;
  top:50%; right:14px;
  transform:translateY(-50%);
  color:#9FB3CC;
  font-size:13px;
}
.nl-field input{
  width:100%;
  height:46px;
  border-radius:12px;
  border:1.5px solid var(--line);
  background:#F7FAFD;
  padding:0 40px 0 14px;
  font-size:13px;
  color:var(--ink);
  outline:none;
  transition:border-color .25s ease, background .25s ease, box-shadow .25s ease;
}
.nl-field input::placeholder{color:#B3C0D1;}
.nl-field input:focus{
  border-color:var(--blue-2);
  background:#fff;
  box-shadow:0 0 0 4px rgba(45,156,219,.14);
}

.nl-btn{
  width:100%;
  height:46px;
  border:none;
  border-radius:12px;
  background:linear-gradient(120deg, var(--navy), var(--blue-2));
  color:#fff;
  font-size:13.5px;
  font-weight:700;
  cursor:pointer;
  display:flex; align-items:center; justify-content:center; gap:8px;
  box-shadow:0 10px 20px rgba(15,62,145,.25);
  transition:transform .25s ease, box-shadow .25s ease, filter .25s ease;
}
.nl-btn:hover{
  transform:translateY(-2px);
  box-shadow:0 14px 26px rgba(15,62,145,.32);
  filter:brightness(1.05);
}
.nl-btn i{font-size:12px;}

/* Gallery card — static single image, no slider */
.gallery-card-body{
  position:relative;
}
.gallery-img-wrap{
  position:relative;
  height:230px;
  overflow:hidden;
}
.gallery-img-wrap img{
  width:100%; height:100%;
  object-fit:cover;
  display:block;
  transition:transform .6s ease;
}
.gallery-card:hover .gallery-img-wrap img{
  transform:scale(1.05);
}

/* ============ CENTER COLUMN: News/Announcements ============ */
.cb2-center{
  background:#fff;
  border-radius:15px;
  box-shadow:var(--shadow-1);
  overflow:hidden;
  border:1px solid rgba(15,62,145,.05);
  display:flex;
  flex-direction:column;
}

.news-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:18px 22px 0;
}

.news-tabs2{
  display:inline-flex;
  background:#F1F5FA;
  padding:5px;
  border-radius:14px;
  gap:4px;
  position:relative;
}
.news-tab-btn{
  border:none;
  background:transparent;
  padding:9px 22px;
  font-size:13px;
  font-weight:600;
  color:var(--muted);
  border-radius:10px;
  cursor:pointer;
  position:relative;
  z-index:2;
  transition:color .3s ease;
  white-space:nowrap;
}
.news-tab-btn.active{ color:#fff; }
.news-tab-slider{
  position:absolute;
  top:5px;
  left:5px;
  height:calc(100% - 10px);
  width:120px;
  background:linear-gradient(120deg, var(--navy), var(--blue));
  border-radius:10px;
  box-shadow:0 8px 18px rgba(15,62,145,.28);
  transition:left .35s cubic-bezier(.4,0,.2,1), width .35s cubic-bezier(.4,0,.2,1);
  z-index:1;
}

.news-count-pill{
  font-size:11.5px;
  color:var(--navy);
  background:var(--blue-soft);
  padding:6px 14px;
  border-radius:20px;
  font-weight:600;
  display:flex; align-items:center; gap:6px;
}
.news-count-pill i{font-size:9px;}

.news-list2{
  padding:18px 22px 22px;
  display:flex;
  flex-direction:column;
  gap:14px;
  max-height:400px;
  overflow-y:auto;
}
.news-list2::-webkit-scrollbar{width:5px;}
.news-list2::-webkit-scrollbar-thumb{background:#D7E3F0; border-radius:10px;}

.news-card2{
  display:flex;
  gap:16px;
  border-radius:16px;
  padding:12px;
  position:relative;
  transition:background .3s ease, transform .3s ease, box-shadow .3s ease;
  cursor:pointer;
  border:1px solid transparent;
}
.news-card2:hover{
  background:#F8FAFD;
  border-color:var(--line);
  transform:translateX(-4px);
  box-shadow:0 12px 24px rgba(15,62,145,.08);
}

.news-card2 .thumb{
  width:110px; height:88px;
  flex-shrink:0;
  border-radius:12px;
  overflow:hidden;
  position:relative;
}
.news-card2 .thumb img{
  width:100%; height:100%; object-fit:cover;
  transition:transform .5s ease;
}
.news-card2:hover .thumb img{transform:scale(1.1);}

.news-card2 .thumb .cat-badge{
  position:absolute;
  top:6px; right:6px;
  background:rgba(0,71,122,.85);
  color:#fff;
  font-size:9.5px;
  font-weight:600;
  padding:3px 8px;
  border-radius:6px;
  backdrop-filter:blur(2px);
}

.news-card2 .content{
  flex:1;
  min-width:0;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:6px;
}
.news-card2 .content h4{
  font-size:14px;
  font-weight:700;
  color:var(--ink);
  line-height:1.6;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.news-card2 .content p{
  font-size:12px;
  color:var(--muted);
  line-height:1.7;
  display:-webkit-box;
  -webkit-line-clamp:1;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.news-card2 .meta{
  display:flex;
  align-items:center;
  gap:10px;
  font-size:11px;
  color:#9AA9BC;
}
.news-card2 .meta i{font-size:10px; color:var(--blue-2);}

.news-card2 .go-arrow{
  width:30px; height:30px;
  border-radius:50%;
  background:var(--blue-soft);
  color:var(--navy);
  display:flex; align-items:center; justify-content:center;
  align-self:center;
  flex-shrink:0;
  opacity:0;
  transform:translateX(6px);
  transition:.3s ease;
  font-size:12px;
}
.news-card2:hover .go-arrow{
  opacity:1;
  transform:translateX(0);
  background:var(--navy);
  color:#fff;
}

.news-footer2{
  padding:14px 22px 20px;
  border-top:1px solid var(--line);
  display:flex;
  justify-content:center;
}
.news-more-btn{
  display:flex; align-items:center; gap:8px;
  font-size:12.5px;
  font-weight:600;
  color:var(--navy);
  text-decoration:none;
  padding:9px 20px;
  border:1.5px solid var(--line);
  border-radius:12px;
  transition:.25s ease;
}
.news-more-btn:hover{
  background:var(--navy);
  color:#fff;
  border-color:var(--navy);
}

/* ============ RIGHT COLUMN: Links ============ */
.cb2-right{
  background:#fff;
  border-radius:15px;
  box-shadow:var(--shadow-1);
  overflow:hidden;
  border:1px solid rgba(15,62,145,.05);
}
.links-body{
  padding:16px;
  display:flex;
  flex-direction:column;
  gap:14px;
}
.link-item{
  display:block;
  border-radius:14px;
  overflow:hidden;
  position:relative;
  height:86px;
  box-shadow:0 3px 10px rgba(15,62,145,.07);
  transition:transform .35s cubic-bezier(.4,0,.2,1), box-shadow .35s ease;
}
.link-item img{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
  transition:transform .5s ease, filter .5s ease;
}
.link-item:hover{
  transform:translateY(-4px);
  box-shadow:var(--shadow-2);
}
.link-item:hover img{
  transform:scale(1.06);
}
.link-item::after{
  content:'';
  position:absolute;
  inset:0;
  border-radius:14px;
  box-shadow:inset 0 0 0 1px rgba(15,62,145,.08);
  pointer-events:none;
}

/* ============ Responsive ============ */
@media (max-width:1180px){
  .cb2-wrapper{
    grid-template-columns: 1fr 1fr;
  }
  .cb2-right{ grid-column: span 2; }
}
@media (max-width:820px){
  .cb2-wrapper{
    grid-template-columns: 1fr;
  }
  .cb2-right{ grid-column: span 1; }
  .news-card2 .thumb{width:88px; height:74px;}
}
@media (max-width:480px){
  body{padding:20px 12px;}
  .news-top{flex-direction:column; align-items:flex-start; gap:10px;}
  .news-tabs2{width:100%;}
  .news-tab-btn{flex:1;}
  .news-count-pill{align-self:flex-end;}
}

