/* ===== فیلدهای اضافه‌شده برای مودال تعریف اسلایدشو ===== */
.cbn-modal-body {
    max-height: 70vh;
    overflow-y: auto;
}

.cbn-flex-form {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.cbn-flex-field {
    flex: auto;
}

.cbn-flex-field label {
    display: block;
    font-size: 13px;
    margin-bottom: 6px;
    font-weight: 500;

}

.cbn-flex-field input[type="text"],
.cbn-flex-field select {
    width: 100%;
    height: 38px;
    border: 1px solid #e1e5e9;
    border-radius: 8px;
    padding: 0 12px;
    font-size: 13px;
    color: #3d4855;
    background: #fff;
    outline: none;
    transition: border-color .15s ease;
    box-sizing: border-box;
}

.cbn-flex-field input[type="text"]:focus,
.cbn-flex-field select:focus {
    border-color: #139e99;
}

.cbn-flex-field select {
    appearance: none;
    -webkit-appearance: none;
    background: #fff url("/design/shared/83989d6bcbdd4d813c45.svg") no-repeat left 12px center;
    padding-left: 30px;
    cursor: pointer;
}

/* رادیو گروه نوع محتوا */
.cbn-radio-group {
    display: flex;
    align-items: center;
    gap: 18px;
    flex-wrap: wrap;
}

.cbn-radio-item {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    font-size: 13px;
    color: #3d4855;
}

.cbn-radio-item input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 17px;
    height: 17px;
    border: 1.5px solid #c7cdd3;
    border-radius: 50%;
    position: relative;
    cursor: pointer;
    margin: 0;
    transition: border-color .15s ease;
}

.cbn-radio-item input[type="radio"]:checked {
    border-color: #139e99;
}

.cbn-radio-item input[type="radio"]:checked::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 9px;
    height: 9px;
    background: #139e99;
    border-radius: 50%;
    transform: translate(-50%, -50%);
}

/* ناحیه محتوای صفحه (جایگزین ادیتور) */
.cbn-content-editor {
    width: 100%;
    min-height: 160px;
    border: 1px solid #e1e5e9;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 13px;
    color: #3d4855;
    resize: vertical;
    outline: none;
    box-sizing: border-box;
    font-family: inherit;
    transition: border-color .15s ease;
}

.cbn-content-editor:focus {
    border-color: #139e99;
}

/* آپلود تصویر */
.cbn-upload-box {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 44px;
    border: 1.5px dashed #c7cdd3;
    border-radius: 8px;
    background: #fafbfc;
    color: #5b6770;
    font-size: 13px;
    cursor: pointer;
    transition: border-color .15s ease, background .15s ease;
}

.cbn-upload-box:hover {
    border-color: #139e99;
    background: #f2fbfa;
    color: #139e99;
}

.cbn-upload-hint {
    font-size: 11px;
    color: #97a1a8;
    margin-top: 4px;
}

.cbn-upload-preview {
    display: none;
    margin-top: 8px;
    max-width: 100%;
    max-height: 140px;
    border-radius: 8px;
    border: 1px solid #eef0f2;
}

